// D-01: one endpoint for Property Finder, Bayut, Dubizzle, Meta lead ads,
// the company website and anything else that can POST JSON.
const b = $json.body || $json;
const q = $json.query || {};
const pick = (...k) => { for (const x of k) { if (x !== undefined && x !== null && String(x).trim() !== '') return String(x).trim(); } return ''; };

// Meta / Facebook lead-ads arrive as field_data[{name,values[]}]
const meta = {};
if (Array.isArray(b.field_data)) {
  for (const f of b.field_data) meta[f.name] = (f.values || [])[0];
}

const source = pick(q.source, b.source, b.portal, b.origin,
                    b.lead_source, meta.source, 'Website');
const name   = pick(b.name, b.full_name, b.client_name, b.customer_name,
                    b.lead && b.lead.name, meta.full_name, meta.name);
const phone  = pick(b.phone, b.mobile, b.contact, b.phone_number,
                    b.lead && b.lead.phone, meta.phone_number).replace(/[^0-9+]/g, '');
const emailA = pick(b.email, b.email_address, b.lead && b.lead.email, meta.email).toLowerCase();
const prop   = pick(b.property_reference, b.propertyReference, b.reference,
                    b.property_ref, b.listing_reference, b.property, b.message,
                    meta.property);

if (!name && !phone && !emailA) {
  throw new Error('Lead payload had no name, phone or email: ' + JSON.stringify(b).slice(0, 300));
}

return [{ json: {
  source, client_name: name || '(no name given)',
  contact: phone, email: emailA,
  property_interest: prop,
  lead_id: 'L-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' +
           Math.random().toString(36).slice(2, 7).toUpperCase(),
  raw: JSON.stringify(b).slice(0, 4000),
}}];
